const getCategoryImage = (project, projectType) => {
  const category = [
    findDatabaseValue(project, ["Category", "ProjectCategory"]),
    projectType
  ].map((value) => formatDatabaseValue(value).toLowerCase()).join(" ");

  if (category.includes("plotted")) {
    return plottedImage;
  }
  if (category.includes("commercial")) {
    return commercialImage;
  }
  if (category.includes("residential")) {
    return residentialImage;
  }

  return project?.ImageUrl || project?.ThumbnailUrl || FALLBACK_IMAGE;
};

