import { useCallback, useEffect, useRef, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "../styles/ventures.css";
import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import FilterBar, { DEFAULT_FILTER_VALUES } from "./components/FilterBar";
import PropertySection from "./components/PropertySection";
import AIAdvisorSection from "./components/AIAdvisorSection";
import PropifyAcademyAd from "./components/PropifyAcademyAd";
import Footer from "./components/Footer";
import InvestmentModal from "./components/InvestmentModal";
import { searchVentures } from "./services/ventureApi";

const PAGE_SIZE = 10;
const NO_APPLIED_FILTERS = {};

function App() {
  const [filterValues, setFilterValues] = useState(DEFAULT_FILTER_VALUES);
  const [appliedFilters, setAppliedFilters] = useState(NO_APPLIED_FILTERS);
  const [selectedReraNo, setSelectedReraNo] = useState("");
  const [searchInput, setSearchInput] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  const [suggestions, setSuggestions] = useState([]);
  const [projects, setProjects] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [pageNumber, setPageNumber] = useState(1);
  const [isProjectsLoading, setIsProjectsLoading] = useState(false);
  const [projectsError, setProjectsError] = useState("");
  const [isSuggestionsLoading, setIsSuggestionsLoading] = useState(false);
  const [suggestionsError, setSuggestionsError] = useState("");
  const [isInvestmentModalOpen, setIsInvestmentModalOpen] = useState(false);
  const suggestionRequestId = useRef(0);

  const loadProjects = useCallback(async (query, page, filters) => {
    setIsProjectsLoading(true);
    setProjectsError("");

    try {
      const result = await searchVentures({
        query,
        pageNumber: page,
        pageSize: PAGE_SIZE,
        filters
      });

      setProjects(result.items);
      setTotalCount(result.totalCount);
    } catch (error) {
      setProjects([]);
      setTotalCount(0);
      setProjectsError(error?.message || "Unable to load projects right now.");
    } finally {
      setIsProjectsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadProjects(searchQuery, pageNumber, appliedFilters);
  }, [appliedFilters, loadProjects, pageNumber, searchQuery]);

  useEffect(() => {
    const query = searchInput.trim();
    const requestId = ++suggestionRequestId.current;

    setSuggestions([]);
    setSuggestionsError("");

    if (!query) {
      setIsSuggestionsLoading(false);
      return undefined;
    }

    setIsSuggestionsLoading(true);
    const debounceTimer = setTimeout(async () => {
      try {
        const result = await searchVentures({
          query,
          pageNumber: 1,
          pageSize: 5
        });

        if (requestId !== suggestionRequestId.current) {
          return;
        }

        const nextSuggestions = result.items.map((item) => item?.ProjectName || item?.projectName || "").filter(Boolean);
        setSuggestions(Array.from(new Set(nextSuggestions)).slice(0, 5));
      } catch (error) {
        if (requestId !== suggestionRequestId.current) {
          return;
        }

        setSuggestionsError(error?.message || "Unable to load matching ventures.");
      } finally {
        if (requestId === suggestionRequestId.current) {
          setIsSuggestionsLoading(false);
        }
      }
    }, 300);

    return () => clearTimeout(debounceTimer);
  }, [searchInput]);

  const handleSearchSubmit = (value) => {
    const nextQuery = value.trim();
    const normalizedRera = nextQuery.replace(/\s+/g, "");
    const isReraSearch = /^P\d{5,}$/i.test(normalizedRera);

    setSearchInput(value);
    setSearchQuery(nextQuery);
    setSelectedReraNo(isReraSearch ? normalizedRera : "");
    setPageNumber(1);
  };

  return <div style={{ minHeight: "100vh", background: "#f1f5f9" }}>
      {
    /* Sticky Navbar */
  }
      <Navbar onAdvisorClick={() => setIsInvestmentModalOpen(true)} />
      <InvestmentModal open={isInvestmentModalOpen} onOpenChange={setIsInvestmentModalOpen} />

      {
    /* Hero — full bleed city bg */
  }
      <Hero
    searchValue={searchInput}
    onSearchChange={setSearchInput}
    onSearchSubmit={handleSearchSubmit}
    suggestions={suggestions}
    isSuggestionsLoading={isSuggestionsLoading}
    suggestionsError={suggestionsError}
  />

      {
    /* Filter bar overlaps hero bottom */
  }
      <FilterBar
        values={filterValues}
        onChange={setFilterValues}
        onApply={setAppliedFilters}
      />

      {
    /* AI Insight strip */
  }
    

      {
    /* Property Cards + Map */
  }
      <PropertySection
        builderName={appliedFilters.builderName}
        reraNo={selectedReraNo}
        searchQuery={searchQuery}
        filters={appliedFilters}
      />

      {
    /* AI Advisor Cards + Popular Comparisons */
  }
      <section className="vd-advisor-section">
        <div className="row g-3">
          <div className="col-12 col-lg-8">
            <AIAdvisorSection onAdvisorClick={() => setIsInvestmentModalOpen(true)} />
          </div>
          <div className="col-12 col-lg-4">
            <PropifyAcademyAd />
          </div>
        </div>
      </section>

      {
    /* Footer / Bank Strip */
  }
      <Footer />
    </div>;
}
export {
  App as default
};
